import * as THREE from 'three';
function rng(seed=1){let s=seed>>>0;return()=>((s=(s*1664525+1013904223)>>>0)/4294967296)}
function shadows(g){g.traverse(n=>{if(n.isMesh){n.castShadow=true;n.receiveShadow=true}});return g}
